def largestComponentSize(nums):
    # Helper to find all prime factors of a number
    def get_factors(x):
        factors = set()
        d = 2
        while d * d <= x:
            if x % d == 0:
                factors.add(d)
                while x % d == 0:
                    x //= d
            d += 1
        if x > 1:
            factors.add(x)
        return factors

    # Union Find initialization
    parent = {}
    def find(x):
        parent.setdefault(x, x)
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:  # Path compression (iterative, avoids deep recursion)
            parent[x], x = root, parent[x]
        return root
    def union(x, y):
        parent.setdefault(x, x)
        parent.setdefault(y, y)
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # For each number, union all its factors with the number
    for num in nums:
        for factor in get_factors(num):
            union(num, factor)

    # Count the number of elements in each connected component (by their root)
    count = {}
    res = 0
    for num in nums:
        root = find(num)
        count[root] = count.get(root, 0) + 1
        res = max(res, count[root])
    return res
